class Solution:
    def padToPalindrome(self, s: str) -> str:
        k = len(s)
        while k > 0:
            i, j = 0, k - 1
            while i < j and s[i] == s[j]:
                i, j = i + 1, j - 1
            if i >= j:
                break
            k -= 1
        return s[k:][::-1] + s

