class Solution {
    public String padToPalindrome(String s) {
        int k = s.length();
        for (; k > 0; k--) {
            int i = 0, j = k - 1;
            while (i < j && s.charAt(i) == s.charAt(j)) { i++; j--; }
            if (i >= j) break;
        }
        return new StringBuilder(s.substring(k)).reverse() + s;
    }
}

