char* padToPalindrome(char* s) {
    int n = strlen(s), k = n;
    for (; k > 0; k--) {
        int i = 0, j = k - 1;
        while (i < j && s[i] == s[j]) { i++; j--; }
        if (i >= j) break;
    }
    int add = n - k, pos = 0;
    char* out = malloc(add + n + 1);
    for (int i = n - 1; i >= k; i--) out[pos++] = s[i];
    memcpy(out + pos, s, n + 1);
    return out;
}

