class Solution:
    def padToPalindrome(self, s: str) -> str:
        t = s + "#" + s[::-1]
        fail, k = [0] * len(t), 0
        for i in range(1, len(t)):
            while k and t[i] != t[k]:
                k = fail[k - 1]
            if t[i] == t[k]:
                k += 1
            fail[i] = k
        keep = fail[-1]
        return s[keep:][::-1] + s

