class Solution {
public:
    string padToPalindrome(string& s) {
        string rev(s.rbegin(), s.rend());
        string t = s + "#" + rev;
        vector<int> fail(t.size(), 0);
        for (int i = 1, k = 0; i < (int) t.size(); i++) {
            while (k > 0 && t[i] != t[k]) k = fail[k - 1];
            if (t[i] == t[k]) k++;
            fail[i] = k;
        }
        int keep = fail.back();
        return rev.substr(0, s.size() - keep) + s;
    }
};

