char* padToPalindrome(char* s) {
    int n = strlen(s), len = 2 * n + 1;
    char* t = malloc(len);
    for (int i = 0; i < n; i++) { t[i] = s[i]; t[len - 1 - i] = s[i]; }
    t[n] = '#';
    int* fail = calloc(len, sizeof(int));
    for (int i = 1, k = 0; i < len; i++) {
        while (k > 0 && t[i] != t[k]) k = fail[k - 1];
        if (t[i] == t[k]) k++;
        fail[i] = k;
    }
    int keep = fail[len - 1], add = n - keep;
    char* out = malloc(add + n + 1);
    memcpy(out, t + n + 1, add);
    memcpy(out + add, s, n + 1);
    free(t); free(fail);
    return out;
}
